package com.dawnduskterminal.world;

import com.dawnduskterminal.registry.ModTerrainBlocks;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.NoiseChunk;

import java.util.IdentityHashMap;
import java.util.Map;

/**
 * The vein fillers {@code OreVeinifier} hardcodes, remapped to the chrono palette.
 *
 * <p>Vanilla's large ore veins are not a feature, they are generated by code:
 * {@code OreVeinifier.VeinType} bakes the block states into two enum constants -
 *
 * <pre>
 * COPPER(Blocks.COPPER_ORE, Blocks.RAW_COPPER_BLOCK, Blocks.GRANITE,  0,  50)
 * IRON  (Blocks.DEEPSLATE_IRON_ORE, Blocks.RAW_IRON_BLOCK, Blocks.TUFF, -60, -8)
 * </pre>
 *
 * <p>so with {@code ore_veins_enabled: true} the dimension grows vanilla granite and vanilla tuff
 * whatever the datapack says. The ore blocks themselves are left alone - only the two fillers that
 * stand in for stone are swapped, which is what the palette asks for.
 */
public final class ChronoVeinPalette {
    private ChronoVeinPalette() {}

    private static final class Holder {
        static final Map<Block, Block> FILLERS = build();
    }

    private static Map<Block, Block> build() {
        Map<Block, Block> map = new IdentityHashMap<>();
        map.put(Blocks.GRANITE, ModTerrainBlocks.OCHRE.get());
        map.put(Blocks.TUFF, ModTerrainBlocks.TWILIGHT_STONE.get());
        return map;
    }

    /**
     * @return the replacement state, or the input unchanged when this block is not a hardcoded vein
     *     filler. {@code null} passes straight through: the chunk's block rule uses null to mean
     *     "leave the default block here", and that is the common case.
     */
    public static BlockState remap(BlockState state) {
        if (state == null) {
            return null;
        }
        Block replacement = Holder.FILLERS.get(state.getBlock());
        return replacement == null ? state : replacement.defaultBlockState();
    }

    /**
     * Wraps a chunk block rule so the hardcoded vein fillers come out as palette blocks.
     *
     * <p>{@code BlockStateFiller#calculate} is {@code @Nullable} and returns {@code null} for "leave
     * the default block here", which is by far the common case - the null has to pass straight
     * through. Getting that wrong NPEs on nearly every block and no chunk ever finishes, so it lives
     * here in a testable method instead of inline in the mixin.
     */
    public static NoiseChunk.BlockStateFiller wrap(NoiseChunk.BlockStateFiller original) {
        return context -> {
            BlockState state = original.calculate(context);
            return state == null ? null : remap(state);
        };
    }
}
